    private val mod2=1000000009L;
    private val base=911382323L;
    fun distinctEchoSubstrings(text:String):Int{
        val n=text.length;
        val p1=LongArray(n+1);
        val p2=LongArray(n+1);
        val pow1=LongArray(n+1);
        val pow2=LongArray(n+1);
        pow1[0]=1;
        pow2[0]=1;
        for(i in text.indices){
            p1[i+1]=(p1[i]*base+text[i].code)%mod1;
            p2[i+1]=(p2[i]*base+text[i].code)%mod2;
            pow1[i+1]=pow1[i]*base%mod1;
            pow2[i+1]=pow2[i]*base%mod2
        };
        fun hash(prefix:LongArray,power:LongArray,left:Int,right:Int,mod:Long):Long{
            return (prefix[right]-prefix[left]*power[right-left]%mod+mod)%mod
        };
        val seen=mutableSetOf<Long>();
        for(half in 1..n/2)for(start in 0..n-2*half){
            val a1=hash(p1,pow1,start,start+half,mod1);
            val b1=hash(p1,pow1,start+half,start+2*half,mod1);
            if(a1!=b1)continue;
            val a2=hash(p2,pow2,start,start+half,mod2);
            val b2=hash(p2,pow2,start+half,start+2*half,mod2);
            if(a2==b2)seen.add(a1*mod2+a2)
        };
        return seen.size
    }
}

